@scope ([data-rustify-style-owner="old"]) to ([data-rustify-style-owner]) {
  :scope {
    --ease: linear;
  }
  .main-motion {
    animation: rustify-old-card 1s var(--ease) infinite;
  }
  .other-motion {
    animation-name: rustify-old-linear;
    animation-duration: 2s;
  }
}
@keyframes rustify-old-card {
  to {
    opacity: 0;
  }
}
@keyframes rustify-old-linear {
  to {
    opacity: 0.5;
  }
}

@scope ([data-rustify-style-owner="new"]) to ([data-rustify-style-owner]) {
  :scope {
    --ease: rustify-new-linear;
  }
  .main-motion {
    animation: rustify-new-card 1s var(--ease) infinite;
  }
  .other-motion {
    animation-name: rustify-new-linear;
    animation-duration: 2s;
  }
}
@keyframes rustify-new-card {
  to {
    opacity: 0;
  }
}
@keyframes rustify-new-linear {
  to {
    opacity: 0.5;
  }
}
